from lib import *
S = SS('q4')
steps = [
    step("5 条消息的队列,用 basic_get 取走 3 条但不 ack:(ready, unacked) 从 (5, 0) 变成 (2, 3)——消息没有从队列里消失,只是从“待投递”变成“未确认”。ack m1 之后是 (2, 2);再对 m3 的 tag 做 ack(multiple=True),m2 也一并确认,变成 (2, 0)。ack 之前 broker 一直为这几条消息保留着,确认才是“可以删了”的信号。", t=tl(S(1)), mark=lidx(S(1), '不 ack', 'multiple=True'), done=lidx(S(1), '初始', 'ack m1 之后'), b=bars([['初始 ready', 5, '5'], ['取 3 条后 ready', 2, '2'], ['取 3 条后 unacked', 3, '3'], ['ack 全部后 unacked', 0, '0']], 5, mark=[2], done=[0, 1, 3]), kv=KV([['ready', '等着投递的'], ['unacked', '已投递、等 ack 的'], ['ack(multiple=True)', '确认这个 tag 及之前所有的']], ['unacked'])),
    step("nack 并 requeue=True:取到 m1、m2 后 nack m1,接着再取 4 条得到 [m1(redelivered=True)、m3、m4、m5]——m1 回到了队首,而不是队尾,而且标志位 redelivered 变成 True。把 channel 关掉,仍未确认的 m2~m5(以及重新取走的 m1)全部回到队列,(ready, unacked) = (5, 0);再取一遍是 m1~m5 原来的顺序,redelivered 全是 True。", t=tl(S(2)), mark=lidx(S(2), "nack(m1", '再取全部'), done=lidx(S(2), '取到 m1', 'channel 关闭后'), kv=KV([['requeue=True', '回到原来的位置(队首),不是队尾'], ['redelivered', '变成 True'], ['channel 关闭', '所有未确认的消息自动回队列']], ['requeue=True'])),
    step("reject 一次一条,nack 可以 multiple=True 一次一批。6 条全取走后:reject(m1, requeue=False) → (ready, unacked) = (0, 5);nack(m4, multiple=True, requeue=False) 一次丢掉 m2~m4 → (0, 2);nack(m6, multiple=True, requeue=True) 把 m5、m6 放回 → (2, 0),取出来是 m5、m6,redelivered 都是 True。requeue=False 在没有配置死信时就是直接丢弃(死信见后面一篇)。", t=tl(S(3)), mark=lidx(S(3), 'reject(m1', 'nack(m4', 'nack(m6'), done=lidx(S(3), '队列里剩下'), kv=KV([['reject', '一条,requeue 可选'], ['nack', '可 multiple=True 批量(AMQP 标准之外的 RabbitMQ 扩展)'], ['requeue=False', '无死信配置时丢弃']], ['nack'])),
    step("delivery tag 是每个 channel 自己的编号:channel A 收到 tag=1 的消息,channel B 拿同一个 tag=1 去 ack,broker 回 406 PRECONDITION_FAILED unknown delivery tag 1,channel B 被关掉;channel A 的确认仍然有效,最后 (ready, unacked) = (1, 0)。所以确认必须回到收到消息的那个 channel 上做——在多线程里把 channel 共享来共享去、或者消息处理完换了 channel 再 ack,都是这个坑。", t=tl(S(4)), mark=lidx(S(4), '406'), done=lidx(S(4), 'channel A 仍可确认'), kv=KV([['delivery tag', '每个 channel 从 1 开始'], ['跨 channel ack', '406,出错的 channel 被关'], ['处理完再 ack', '必须在同一个 channel']], ['delivery tag'])),
    step("消费者“崩溃”时未确认的消息去哪:队列里 4 条,取走 3 条后直接关闭连接。auto_ack=True(取走即确认)时,(ready, unacked) = (1, 0)——那 3 条已经算处理完,随消费者一起丢了;auto_ack=False 时是 (4, 0)——3 条未确认消息回到队列,又变成 ready。这就是手动确认的意义:处理完才 ack,崩溃就重投。", t=tl(S(5)), mark=lidx(S(5), 'auto_ack=True'), done=lidx(S(5), 'auto_ack=False'), b=bars([['auto_ack=True', 1, '队列剩 1 条'], ['auto_ack=False', 4, '队列剩 4 条']], 4, mark=[0], done=[1]), kv=KV([['auto_ack=True', '消费者崩溃 → 丢 3 条'], ['auto_ack=False', '崩溃 → 3 条回队列'], ['代价', '手动确认可能重复投递']], ['auto_ack=True'])),
    step("总是 nack(requeue=True) 的消费者碰到一条“毒消息”:它在 1 秒内被反复投递了 11967 次,第 1 次 redelivered=False,之后全部是 True。这条消息永远排在队首、永远处理失败,把一个消费者的 CPU 吃满,后面的消息还被它堵住。经典队列只有 redelivered 这一个布尔值,没有计数,所以消费者数不出已经重试了几次;要限制重试需要死信队列或 quorum 队列的 delivery-limit(后面的文章会实测)。", t=tl(S(6)), mark=lidx(S(6), '1 秒内同一条消息'), done=lidx(S(6), '经典队列只带'), b=bars([['1 秒内被投递次数', 11967, '11967 次']], 11967, mark=[0]), kv=KV([['毒消息 + requeue=True', '无限循环,1 秒 11967 次'], ['redelivered', '只有布尔值,没有计数'], ['出路', '死信队列 / delivery-limit / 应用侧计数']], ['毒消息 + requeue=True'])),
]
A = mkartq('q4', 4, 'RabbitMQ,ack,nack,reject,requeue,redelivered,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上实测消息确认:ack 前消息是 unacked 不是消失;nack requeue=True 的消息回到队首且 redelivered 变 True;nack multiple=True 一次丢一批;delivery tag 是每个 channel 自己的,跨 channel 确认得 406;auto_ack 的消息随消费者丢失;requeue 的毒消息 1 秒被投递 11967 次。',
    'ack、nack、reject 三个动作和 requeue 这个开关,到底分别让消息去哪?拒绝的消息回到队首还是队尾?确认可以换个 channel 做吗?消费者崩溃时手动确认和自动确认差在哪?一个总是 requeue 的消费者会造成什么?这篇用 rabbitmqctl 实时读 ready / unacked 数,一项项量。',
    [('(2, 3)', '取走 3 条不 ack 之后的 (ready, unacked):消息只是“未确认”,没有消失'), ('406', '用另一个 channel 确认别人收到的 delivery tag,broker 回的错误码'), ('11967 次', '一条毒消息在 1 秒内被 nack(requeue=True) 反复投递的次数')],
    [('未确认状态', '<p>消息投递给消费者后进入 unacked,ready 和 unacked 之和不变。只有 ack 才让 broker 删除它;<code>multiple=True</code> 一次确认到这个 tag 为止的所有消息。</p>'),
     ('requeue 回到哪', '<p><code>nack</code> / <code>reject</code> 加 <code>requeue=True</code> 时消息放回队列原来的位置(这里是队首),<code>redelivered</code> 标志变成 True;channel 或连接关闭时所有未确认的消息自动回队列,顺序保持不变。</p>'),
     ('丢弃与批量', '<p><code>reject</code> 一次一条;<code>nack</code> 是 RabbitMQ 支持的扩展,能加 <code>multiple=True</code> 一次处理一批。<code>requeue=False</code> 在没有配置死信交换机时就是丢弃。</p>'),
     ('delivery tag', '<p>delivery tag 是每个 channel 自己的递增编号。换一个 channel 用同一个 tag 去确认会得到 406 PRECONDITION_FAILED,并且那个 channel 被关闭。</p>'),
     ('自动确认', '<p>auto_ack(no_ack)时消息一投出去就算确认,消费者崩溃时在途的消息就丢了;手动确认时这些消息回到队列,代价是可能被重复投递(后面有一篇讲幂等)。</p>'),
     ('毒消息', '<p>总是 requeue 的消费者会让同一条消息不停地循环。经典队列只有一个 redelivered 布尔值,无法限制次数。</p>')],
    steps,
    [ENV_Q + '。ready / unacked 数来自 rabbitmqctl list_queues(实时,管理 API 的统计有几秒延迟);第一~五节用 basic_get 取消息以保证顺序可复现,第六节用 basic_consume 加回调;每个小实验开始前 purge 并重新发布',
     '没有验证:quorum 队列和 stream 队列上同样操作的行为(requeue 位置、delivery-count);带 prefetch 的推送消费者下 requeue 的顺序(这里用 basic_get 和单个 consumer);批量 nack 的确认跨过已经 ack 过的 tag 的行为;consumer_timeout 对未确认消息的影响(见后面一篇);多个消费者之间的 requeue 公平性'],
    '消息确认')
